INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES
('4703eef3-172f-5259-9cb7-b2f0f7631167', '2730654b-b63f-559d-8516-115198cbc456', 'tr', $h$Havalı Yağ Boşaltma Deposu Tankı 60 Lt – 4260$h$, $h$havali-yag-bosaltma-deposu-tanki-60-lt-4260$h$, NULL, $h$<div> <div><p><strong>Neden 4260 Havalı Yağ Boşaltma Deposu ?</strong></p><p>Havalı yağ boşaltma tankı motor ve dişli kutusundan boşaltılan atık yağların toplanması içindir. Teleskobik huni ile tank içerisine atık yağları toplayabilmekte ve buradaki kullanılmış yağ miktarı tank scala`sından takip edilmektedir. 60 Lt depo kullanım kapasitesi mevcuttur. Teleskopik huni sayesinde araç lifte kaldırılıp tapa sökülerek kullanılabilmektedir. İki sabit iki dönerli teker sayesinde hareket kabiliyeti yüksektir. Tank içerisindeki atık yağ tahliyesi hava ile yapılmaktadır. Tank üzerinde bulunan emniyet ventili aşırı hava basınçlarına karşı koruma sağlar. Paslandırıcı ve parlayıcı sıvılarda kullanılmaması gerekir.</p></div> </div>$h$, NULL, $h$Havalı Yağ Boşaltma Deposu Tankı 60 Lt – 4260 | HD Marine$h$, $h$Neden 4260 Havalı Yağ Boşaltma Deposu ? Havalı yağ boşaltma tankı motor ve dişli kutusundan boşaltılan atık yağların toplanması içindir. Teleskobik huni…$h$, 'reviewed'),
('01c9a073-3b5f-5cf1-8f74-9d66a3e56ffa', 'd5cabf79-885c-5225-ad32-481816214c7a', 'tr', $h$Havalı Yağ Boşaltma Deposu Tankı 80 Lt – 4290$h$, $h$havali-yag-bosaltma-deposu-tanki-80-lt-4290$h$, NULL, $h$<div> <div><p><strong>Neden 4290 Havalı Yağ Boşaltma Deposu ?</strong></p><p>Havalı yağ boşaltma tankı motor ve dişli kutusundan boşaltılan atık yağların toplanması içindir. Teleskobik huni ile tank içerisine atık yağları toplayabilmekte ve buradaki kullanılmış yağ miktarı tank scala`sından takip edilmektedir. 80 Lt depo kullanım kapasitesi mevcuttur. Teleskopik huni sayesinde araç lifte kaldırılıp tapa sökülerek kullanılabilmektedir. İki sabit iki dönerli teker sayesinde hareket kabiliyeti yüksektir. Tank içerisindeki atık yağ tahliyesi hava ile yapılmaktadır. Tank üzerinde bulunan emniyet ventili aşırı hava basınçlarına karşı koruma sağlar. Paslandırıcı ve parlayıcı sıvılarda kullanılmaması gerekir.</p></div> </div>$h$, NULL, $h$Havalı Yağ Boşaltma Deposu Tankı 80 Lt – 4290 | HD Marine$h$, $h$Neden 4290 Havalı Yağ Boşaltma Deposu ? Havalı yağ boşaltma tankı motor ve dişli kutusundan boşaltılan atık yağların toplanması içindir. Teleskobik huni…$h$, 'reviewed'),
('379262e4-8c94-55db-9be0-347e96839cc5', '52d6278b-6ea6-53dc-b5ba-b0408f9330d4', 'tr', $h$Yağ Boşaltma Kovası 50 Lt – 4250$h$, $h$yag-bosaltma-kovasi-50-lt-4250$h$, NULL, $h$<div> <div><p><strong>Neden 4250 Yağ Boşaltma Kovası ?</strong></p><p>Yağ boşaltma kovasıyla motor ve dişli kutusundan boşalan atık yağları toplarsınız. Kova 50 litre depolama kapasitesi sunar. Teleskopik hunisi sayesinde aracı lifte kaldırır, tapasını sökerek kovayı kullanırsınız. Dört adet döner tekerlek ona yüksek hareket kabiliyeti verir. Tanktaki atık yağı manuel tahliye edersiniz. Paslandırıcı ve parlayıcı sıvılarda onu kullanmayın. Onu yoğun kullanmadığınız yerler için tasarladık. Kolay taşıma sağlar ve ekonomik bir modeldir.</p></div> </div>$h$, NULL, $h$Yağ Boşaltma Kovası 50 Lt – 4250 | HD Marine$h$, $h$Neden 4250 Yağ Boşaltma Kovası ? Yağ boşaltma kovasıyla motor ve dişli kutusundan boşalan atık yağları toplarsınız. Kova 50 litre depolama kapasitesi…$h$, 'reviewed'),
('6cf39d42-f251-58ab-8f1b-334ab3dd2151', '9044da7d-4dcc-5945-bfc7-e617349771fc', 'tr', $h$Metal Litre Kapları – LTK$h$, $h$metal-litre-kaplari-ltk$h$, NULL, $h$<div> <div><p><strong>Neden LTK Metal Litre Kapları ?</strong></p><p>Sağlam gövde yapısına sahiptir, ergonomik tutacağı taşımayı ve dökmeyi kolaylaştırır.</p></div> </div>$h$, NULL, $h$Metal Litre Kapları – LTK | HD Marine$h$, $h$Neden LTK Metal Litre Kapları ? Sağlam gövde yapısına sahiptir, ergonomik tutacağı taşımayı ve dökmeyi kolaylaştırır.$h$, 'reviewed'),
('12c45474-2eab-5dc0-8419-a5486c176c64', 'b366bf85-d795-5a94-9a10-5878479fbc51', 'tr', $h$Plastik Litre Kapları – LKP$h$, $h$plastik-litre-kaplari-lkp$h$, NULL, $h$<div> <p><strong>Neden LKP Plastik Litre Kabı ?</strong></p><p>Hem litre hem de galon ölçeği. Profesyonel kullanım için dayanıklı plastik.</p><div> </div><div><div><img alt="Plastik litre kapları. Yağ, sıvı ve kimyasalların hassas ölçümü ve güvenli bir şekilde transferi için kullanılan ölçüm kapları." src="https://www.gulersan.com/wp-content/uploads/2021/03/litre-kablari.jpg"/></div></div> </div>$h$, NULL, $h$Plastik Litre Kapları – LKP | HD Marine$h$, $h$Neden LKP Plastik Litre Kabı ? Hem litre hem de galon ölçeği. Profesyonel kullanım için dayanıklı plastik.$h$, 'reviewed'),
('b6ef95da-e799-5f8d-9818-5f1a47215722', '0520b8cf-8896-5621-8f6d-e21cdfe3f41b', 'tr', $h$Plastik Litre Kapları Kapaklı – LKPK$h$, $h$plastik-litre-kaplari-kapakli-lkpk$h$, NULL, $h$<div> <div><p><strong>Neden LKPK Plastik Litre Kabı ?</strong></p><p>Sıvıyı güvenli bir şekilde saklamak ve taşımak için kapatma kapağı<br/>Ön damlama önleyici kapak<br/>Profesyonel kullanım için dayanıklı plastik.<br/>Hem litre hem de galon ölçeği</p></div> </div>$h$, NULL, $h$Plastik Litre Kapları Kapaklı – LKPK | HD Marine$h$, $h$Neden LKPK Plastik Litre Kabı ? Sıvıyı güvenli bir şekilde saklamak ve taşımak için kapatma kapağı Ön damlama önleyici kapak Profesyonel kullanım için…$h$, 'reviewed'),
('80cd4f24-9f4d-5fc6-91d9-5a2b14e08683', 'ad597699-80c1-53e3-a91f-7b4660c8a4fb', 'tr', $h$Metal Huniler – HN$h$, $h$metal-huniler-hn$h$, NULL, $h$<div> <div><p><strong>Neden HN Metal Huni ?</strong></p><p>Rahat kullanım düşünülerek tasarlanan sağlam metal gövde yapısı, ergonomik tutacak. Motor yağı, dizel, benzin, yağlayıcılar, su transferi için uygundur.</p></div> </div>$h$, NULL, $h$Metal Huniler – HN | HD Marine$h$, $h$Neden HN Metal Huni ? Rahat kullanım düşünülerek tasarlanan sağlam metal gövde yapısı, ergonomik tutacak. Motor yağı, dizel, benzin, yağlayıcılar, su…$h$, 'reviewed'),
('15467939-af53-5738-996b-77e2747ef613', 'e23a45e8-b936-57e7-b3fb-d019ae6564a4', 'tr', $h$Graco Uyumlu Yedek Parça$h$, $h$graco-uyumlu-yedek-parca$h$, $h$Aro® Uyumlu Yedek Parça$h$, $h$<div> <div><p>Aro® havayla çalışan çift diyaframlı pompa ürününü ilk olarak seksenli yıllarda Bryan Ohio’da (Amerika Birleşik Devletleri) piyasaya sürmüştür. Günümüzde ARO®, Ingersoll Rand Corp.’un bir parçası ve başlıca AODD Pump markalarından birisidir.</p></div> </div><div> <div><p>ARO® havayla çalışan diyaframlı pompalar, çeşitli viskoz akışkanları taşımak için kullanım kapasitesi taşır ve durmasız, buzsuz çalışmasını sağlar. Dengesiz hava valfi tasarımı ise diğer pompalarla ilişkili durma sorunlarını önlemektedir. Hızlı boşaltma egzoz valfleri, soğuk egzoz havasını buza eğilimli bileşenlerden yönlendirir ve donmayı engeller. Tahliye edilmesi planlanan sıvının türüne göre pompa kısmı, tek gövdeli, iki gövdeli ya da ağır hizmet tipi iki gövdeli dahil olmak üzere çoklu yapılandırmalar içeren pistonlu pompa paketleri bulunmaktadır.</p><p>ARO® diyaframlı pompalar, uygun maliyeti, güvenilir yapısıyla endüstriyel ve kimyasal uygulamalar için iyi bir seçimdir. Cıvatalı, sızdırmaz yapısı çapraz kontaminasyonu ortadan kaldırmakta ve operatörün güvenliğini artırmaktadır. Modüler yapısı, azaltılmış parça sayısı ve kullanım kolaylığı olan tamir takımları gerekli durumlarda ürünün onarım süresini de en aza indirmektedir.</p><p>HD Marine, çift diyaframlı (AODD) Pompalarına uyum sağlayan yedek parçalarla, güvenilir ve kaliteli ürünlerle sizi buluşturur. HD Marine, tercihinize göre birçok parçanın yedek ürün desteğini sağlamakla birlikte Aro yedek parçalarına<strong> valf topu, valf yuvası, diyafram, conta, kelepçe bantları, susturucular, piston ve valf halkaları</strong> gibi ürünlere ulaşacağınız bir adrestir.</p><p>Diyaframlı Pompalar da herhangi bir arıza ya da bakım durumunda HD Marine sitesi üzerinden Aro markasına uygun ürünleri tek tek tercih edebileceğiniz gibi <strong>Aro Service Kıts</strong> kısmından; vida, conta ve birçok halka çeşitlerinin bir arada bulunduğu servis/tamir kitine ulaşabilirsiniz. Servis kitleri pnömatik çift diyaframlı pompanızın ıslak kısmı için ıslak kit ve hava ile çalışan çift diyaframlı pompanızın hava tarafının bakım onarımında kullanılan kit olarak iki çeşitte karşınıza çıkacaktır. Bu iki kitin içerisinde farklı ürünler bulunacağından dolayı, ihtiyacınız olan ürünlerin neler olduğuna ve hangi alanda kullanacağınızı düşünerek tercih yapmalısınız.</p><p><strong>Aro Service Kıts</strong> dışında ürünleri tek tek almak istediğinizde; <strong>Aro gaskets, Aro ring, Aro valve balls, aro valve seats, aro hardware ve aro diaphragms</strong> çeşitlerine de ulaşabilirsiniz. Ancak her endüstrinin pompaları kullandığı alan ve bu alana uygun kullanılacak Aro yedek parça ürününün değişiklik göstereceği düşünülmelidir. Kimyasal uyumluluk, sıcaklık, sızdırmazlık kapasitesi gibi özel uygulama ihtiyaçlarınıza göre HD Marine pompa parçalarında en yaygın kullanılan, tercih edilen <strong>Santopren, Hytrel, N-fit, PTFE, Neopren </strong>gibi kaliteli malzemeleri ve ürünleri müşterilerine sunmaktadır.</p></div> </div>$h$, NULL, $h$Graco Uyumlu Yedek Parça | HD Marine$h$, $h$Aro® havayla çalışan çift diyaframlı pompa ürününü ilk olarak seksenli yıllarda Bryan Ohio’da (Amerika Birleşik Devletleri) piyasaya sürmüştür. Günümüzde…$h$, 'reviewed'),
('6fbda787-a63d-51cf-8690-758a14d06ed3', '2f042790-8ffd-550e-a331-f0a748541f63', 'tr', $h$Havalı Sabit Yağ Varil Sistemi – DVS4500$h$, $h$havali-sabit-yag-varil-sistemi-dvs4500$h$, NULL, $h$<div> <div><p><strong>Neden DVS4500 Havalı Sabit Yağ Varil Sistemi ?</strong></p><p>Sabit yağ varil sistemlerinin farklı amaçlar için bir çok versiyonu mevcuttur. Farklı verim ve basınç oranlarına sahip pompa seçenekleri, 20 metreye varan hortum uzunlukları, istenildiği sisteme adapte edilebilen litre yazar sayaçlı tabancalar sayesinde oldukça yüksek iş yapabilme kabiliyeti kazandırılmıştır. Her işletmenin ihtiyaç farklılıkları göz önüne alındığında bu sistemler işletmeler için mükemmel bir çözüm sunmaktadır. Yağ varil sistemleri standart 5 parçadan oluşmaktadır,<br/>ancak yağ pompanızı, yağ tabancanızı ve yağ hortum makaranızı siz seçebilirsiniz.</p></div> </div>$h$, NULL, $h$Havalı Sabit Yağ Varil Sistemi – DVS4500 | HD Marine$h$, $h$Neden DVS4500 Havalı Sabit Yağ Varil Sistemi ? Sabit yağ varil sistemlerinin farklı amaçlar için bir çok versiyonu mevcuttur. Farklı verim ve basınç…$h$, 'reviewed'),
('59c62585-b800-536b-abed-479d504d8f70', 'b9bbc9fa-3e1a-5f18-86b8-0d34a9cda087', 'tr', $h$Havalı Sabit Gres Varil Sistemi – DVS2500$h$, $h$havali-sabit-gres-varil-sistemi-dvs2500$h$, NULL, $h$<div> <div><p><strong>Neden DVS2500 Havalı Sabit Gres Varil Sistemi ?</strong></p><p>Duvara monte sabit gres varil sistemlerinin farklı versiyonları mevcuttur. Farklı verim ve basınç oranlarına sahip pompa seçenekleri, 20 metreye varan hortum uzunluklarına sahip hortum makaraları, istenildiğinde sisteme adapte edilebilen sayaçlı gres tabancası vb.ürünler sayesinde sistem yüksek iş yapabilme kabiliyetine sahiptir. Her işletmenin ihtiyaç farklılıkları göz önüne alındığında bu sistemler işletmeler için mükemmel bir çözüm sunmaktadır. Gres varil sistemleri standart 9 parçadan oluşmaktadır ancak gres pompanızı, gres tabancanızı ve gres hortum uzunluğunu siz seçebilirsiniz.</p></div> </div>$h$, NULL, $h$Havalı Sabit Gres Varil Sistemi – DVS2500 | HD Marine$h$, $h$Neden DVS2500 Havalı Sabit Gres Varil Sistemi ? Duvara monte sabit gres varil sistemlerinin farklı versiyonları mevcuttur. Farklı verim ve basınç…$h$, 'reviewed'),
